---@field id number
---@field type apache_superset.ReportScheduleRestApiPutEditorsItemCase1Type

---@alias apache_superset.ReportScheduleRestApiPutEditorsItemCase1Type "user"|"role"|"group"|"subject"

---@alias apache_superset.ReportScheduleRestApiPutEditorsList apache_superset.ReportScheduleRestApiPutEditorsItem[]

---@alias apache_superset.ReportScheduleRestApiPutRecipientsList apache_superset.ReportRecipient[]

